package com.kingoffjoss.pingo;
import android.Manifest;import android.app.Activity;import android.content.Intent;import android.content.ActivityNotFoundException;import android.graphics.Color;import android.net.Uri;import android.os.Build;import android.os.Bundle;import android.provider.Settings;import android.view.View;import android.widget.*;
public class MainActivity extends Activity {
 private TextView status;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(232,244,237));getWindow().setNavigationBarColor(Color.rgb(246,247,240));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);ScrollView scroll=new ScrollView(this);LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);int p=dp(26);page.setPadding(p,p+dp(20),p,p);page.setBackgroundColor(Color.rgb(246,247,240));scroll.addView(page);setContentView(scroll);
  text(page,"PINGO · ANDROID",13);text(page,"Seu pequeno amigo,\nagora pela tela.",31);text(page,"O Pingo aparece sobre a tela inicial e outros aplicativos. Arraste para mudar de lugar; toque nele para abrir os cuidados.",16);status=text(page,"",14);
  button(page,"1. Permitir aparecer sobre outros apps",v->{try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException e){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION));}});
  button(page,"2. Ativar Pingo flutuante",v->{if(!Settings.canDrawOverlays(this)){Toast.makeText(this,"Ative primeiro a permissão de sobreposição.",Toast.LENGTH_LONG).show();return;}try{startForegroundService(new Intent(this,PingoService.class));status.setText("Pingo ativado. Volte à tela inicial para encontrá-lo. Toque nele para ver os controles.");}catch(RuntimeException e){status.setText("Não consegui ativar. Mantenha este aplicativo aberto e tente novamente.");}});
  button(page,"Parar Pingo",v->{stopService(new Intent(this,PingoService.class));status.setText("Pingo fechado.");});
  if(Build.VERSION.SDK_INT>=33)button(page,"Permitir notificação de controle",v->requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},42));
  button(page,"Abrir conversa com IA no navegador",v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://kingoffjoss.github.io/Meus-Scripts/gotinha/mobile.html"))));
  text(page,"Versão de teste 283.0\nO mascote e os cuidados funcionam offline. A conversa com IA abre a página do Pingo. Este app não lê mensagens ou a tela de outros apps. Não liga o microfone em segundo plano.\n\nSe o Android encerrar o app para economizar bateria, abra-o e ative o Pingo novamente. Alguns aplicativos podem bloquear sobreposições.",13);
 }
 @Override public void onResume(){super.onResume();if(status!=null)status.setText(Settings.canDrawOverlays(this)?"Permissão de sobreposição concedida. Você já pode ativar o Pingo.":"Primeiro permita que o Pingo apareça sobre outros apps.");}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(LinearLayout page,String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(Color.rgb(46,91,72));t.setPadding(0,dp(10),0,dp(16));page.addView(t);return t;}
 private void button(LinearLayout page,String title,View.OnClickListener action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setMinHeight(dp(52));b.setTextColor(Color.rgb(40,96,71));page.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(action);}
}
